            long L = sc.nextLong();
            long A = sc.nextLong();
            long B = sc.nextLong();

            long low = 0;
            long high = Math.min(B - A, 5000000L);
            long bestM = 0;

            while (low <= high) {
                long mid = (low + high) >>> 1;
                long sum = mid * A + (mid * (mid - 1)) / 2;
                if (sum < L) {
                    bestM = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            out.println(bestM + 1);
        }

        out.flush();
    }
}
